  "arguments": "{\"action\":\"read\",\"snapshotId\":\"capture-9aba1d48-0f49-4951-9829-4c6a964a4fe8\",\"query\":\"forwardRef deprecated ref cleanups required\",\"segmentIndex\":2}",
