s:\"},{\"charStart\":6954,\"charEnd\":6997,\"text\":\"class MyComponent extends React.Component {\"},{\"charStart\":6999,\"charEnd\":7022,\"text\":\"  componentDidMount() {\"},{\"charStart\":7024,\"charEnd\":7052,\"text\":\"    this.refs.input.focus();\"},{\"charStart\":7075,\"charEnd\":7108,\"text\":\"    return <input ref='input' />;\"},{\"charStart\":7127,\"charEnd\":7170,\"text\":\"class MyComponent extends React.Component {\"},{\"charStart\":7172,\"charEnd\":7195,\"text\":\"  componentDidMount() {\"},{\"charStart\":7243,\"charEnd\":7298,\"text\":\"    return <input ref={input => this.input = input} />;\"},{\"charStart\":7313,\"charEnd\":7352,\"text\":\"Codemod string refs with ref callbacks:\"},{\"charStart\":7354,\"charEnd\":7435,\"text\":\"npx codemod@latest react/19/replace-string-ref\\nRemoved: Module pattern factories \"},{\"charStart\":7437,\"charEnd\":7503,\"text\":\"Module pattern factories were deprecated in August 2019 (v16.9.0).\"},{\"charStart\":7741,\"charEnd\":7770,\"text\":\"function FactoryComponent() {\"},{\"charStart\":7827,\"charEnd\":7856,\"text\":\"function FactoryComponent() {\"},{\"charStart\":7877,\"charEnd\":7908,\"text\":\"}\\nRemoved: React.createFactory \"},{\"charStart\":7910,\"charEnd\":7967,\"text\":\"createFactory was deprecated in February 2020 (v16.13.0).\"},{\"charStart\":8268,\"charEnd\":8332,\"text\":\"const button = <button />;\\nRemoved: react-test-renderer/shallow \"},{\"charStart\":8334,\"charEnd\":8519,\"text\":\"In React 18, we updated react-test-renderer/shallow to re-export react-shallow-renderer. In React 19, we’re removing react-test-render/shallow to prefer installing the package directly:\"},{\"charStart\":8908,\"charEnd\":8973,\"text\":\"Removed deprecated React DOM APIs \\nRemoved: react-dom/test-utils \"},{\"charStart\":9040,\"charEnd\":9228,\"text\":\"Console\\nReactDOMTestUtils.act is deprecated in favor of React.act. Import act from react instead of react-dom/test-utils. See https://react.dev/warnings/react-dom-test-utils for more info.\"},{\"charStart\":9357,\"charEnd\":9641,\"text\":\"All other test-utils functions have been removed. These utilities were uncommon, and made it too easy to depend on low level implementation details of your components and React. In React 19, these functions will error when called and their exports will be removed in a future version.\"},{\"charStart\":9734,\"charEnd\":9806,\"text\":\"npx codemod@latest react/19/replace-act-import\\nRemoved: ReactDOM.render \"},{\"charStart\":9808,\"charEnd\":9964,\"text\":\"ReactDOM.render was deprecated in March 2022 (v18.0.0). In React 19, we’re removing ReactDOM.render and you’ll need to migrate to using ReactDOM.createRoot:\"},{\"charStart\":10263,\"charEnd\":10335,\"text\":\"npx codemod@latest react/19/replace-reactdom-render\\nRemoved: ReactDOM.hy\"}],\"sourcePath\":\"C:\\\\Temp\\\\weftmate-fact1-d4639fa5-93d3-4c19-b0c5-3adfc5860d9e\\\\profile\\\\conversations\\\\aece5e58c4cf64f78c9e3bccc03bda00a1c56ee594e7081cc97810825cad01da\\\\session-3a0d1e90-b75c-49be-8062-fba6e990a659\\\\.weftmate-web-sources\\\\capture-9aba1d48-0f49-4951-9829-4c6a964a4fe8.txt\"}"
