  "arguments": "{\"action\":\"read\",\"snapshotId\":\"capture-f4a25885-90b3-4c30-a3ee-296c70ba6311\",\"query\":\"301 Moved Permanently temporarily automatically redirect 307 308 same request method\",\"segmentIndex\":14}",
