-dom we’re adding <form> Actions to manage forms automatically and useFormStatus to support the common cases for Actions in forms.\"},{\"charStart\":4107,\"charEnd\":4159,\"text\":\"In React 19, the above example can be simplified to:\"},{\"charStart\":4161,\"charEnd\":4203,\"text\":\"// Using <form> Actions and useActionState\"},{\"charStart\":4205,\"charEnd\":4245,\"text\":\"function ChangeName({ name, setName }) {\"},{\"charStart\":4247,\"charEnd\":4305,\"text\":\"  const [error, submitAction, isPending] = useActionState(\"},{\"charStart\":4307,\"charEnd\":4347,\"text\":\"    async (previousState, formData) => {\"},{\"charStart\":4349,\"charEnd\":4408,\"text\":\"      const error = await updateName(formData.get(\\\"name\\\"));\"},{\"charStart\":4462,\"charEnd\":4486,\"text\":\"      redirect(\\\"/path\\\");\"},{\"charStart\":4547,\"charEnd\":4579,\"text\":\"    <form action={submitAction}>\"},{\"charStart\":4581,\"charEnd\":4620,\"text\":\"      <input type=\\\"text\\\" name=\\\"name\\\" />\"},{\"charStart\":4622,\"charEnd\":4686,\"text\":\"      <button type=\\\"submit\\\" disabled={isPending}>Update</button>\"},{\"charStart\":4743,\"charEnd\":4747,\"text\":\"In t\"}],\"sourcePath\":\"C:\\\\Temp\\\\weftmate-fact1-d4639fa5-93d3-4c19-b0c5-3adfc5860d9e\\\\profile\\\\conversations\\\\aece5e58c4cf64f78c9e3bccc03bda00a1c56ee594e7081cc97810825cad01da\\\\session-9c89e02e-6ffd-41df-b71a-2369a1cb8e06\\\\.weftmate-web-sources\\\\capture-e66d7863-4777-452e-a9a1-7a596cd43bef.txt\"}"
        }
